from pathlib import Path
import shutil,hashlib,json
ROOT=Path.cwd();out=ROOT/'artifacts/omni_diagnostics_2026-09-09/pair_load_transfer_001';assert not out.exists();out.mkdir()
for src,dst in [('tmp/reference_pair_results_001','result'),('tmp/reference_pair_preparation_001','preparation'),('tmp/reference_pair_launch_001','launch_guard'),('tmp/reference_pair_figure_001','figure')]:shutil.copytree(ROOT/src,out/dst)
a=json.loads((out/'result/remote_audit.json').read_text());raw=a['raw_payloads'];assert len(raw)==38
for f,h in raw.items():assert hashlib.sha256((out/'result'/f).read_bytes()).hexdigest()==h,f
